  `annotation_id` bigint(20) UNSIGNED NOT NULL,
  `source_id` bigint(20) UNSIGNED NOT NULL,
  `contribution` text DEFAULT NULL,
  `significance_for_dissertation` text DEFAULT NULL,
  `citation_reason` text DEFAULT NULL,
  `adopted_claims` text DEFAULT NULL,
  `limitations` text DEFAULT NULL,
  `scientific_discussion` text DEFAULT NULL,
  `annotation_status` enum('draft','reviewed','approved') NOT NULL DEFAULT 'draft',
  `reviewed_at` datetime DEFAULT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

--
-- Daten für Tabelle `annotations`
--

INSERT INTO `annotations` (`annotation_id`, `source_id`, `contribution`, `significance_for_dissertation`, `citation_reason`, `adopted_claims`, `limitations`, `scientific_discussion`, `annotation_status`, `reviewed_at`) VALUES
(1, 1, 'DEEP RESEARCH 2026-10-17 | Quelle [1]: Rovelli diskutiert im Rahmen der Schleifenquantengravitation, ob die bekannte Raumzeit als fundamentale Beschreibung ausreicht. Dies ist eine Darstellung einer Forschungsrichtung, nicht deren experimenteller Nachweis.', 'Fachlicher Kontext für Kapitel 1.6.1. Quellenbeleg ist von eigener FRZK-Behauptung zu trennen.', 'Zitierte Quelle [1] / Kapitel 1.6.1; Publishers Weekly, Rezension vom 14.11.2016; wortgetreue Wiedergabe Rovellis in Rezension, Buchseite offen', '[SINNGEMAESSER BELEG - NICHT WORTWOERTLICH] Rovelli diskutiert im Rahmen der Schleifenquantengravitation, ob die bekannte Raumzeit als fundamentale Beschreibung ausreicht. Dies ist eine Darstellung einer Forschungsrichtung, nicht deren experimenteller Nachweis.\n[SEKUNDAER_BERICHTET] \"Space is created by the interaction of individual quanta of gravity\"', 'Keine gesicherte Textkontrolle in der zitierten Buchausgabe; keine Aussage, alle physikalischen Theorien gingen von emergenter Raumzeit aus. Originalmanuskript und Einzelaussagen müssen eigenstaendig geprüft werden.', 'Originaltext/Zitatstatus: SEKUNDAER_BERICHTET\nFundort: Publishers Weekly, Rezension vom 14.11.2016; wortgetreue Wiedergabe Rovellis in Rezension, Buchseite offen\nRecherche-URL: https://www.publishersweekly.com/978-0-7352-1392-0\nKeine implizite Freigabe der Seitenzitate oder des FRZK.', 'draft', NULL),
(2, 2, 'DEEP RESEARCH 2026-10-17 | Quelle [2]: Verlinde formuliert in einem theoretischen Forschungsartikel einen Ansatz, der Raumzeit und Gravitation aus quanteninformationellen Verschränkungsstrukturen hervorgehen lässt; die These ist modellabhängig und Gegenstand wissenschaftlicher Prüfung.', 'Fachlicher Kontext für Kapitel 1.6.1. Quellenbeleg ist von eigener FRZK-Behauptung zu trennen.', 'Zitierte Quelle [2] / Kapitel 1.6.1; Abstract, SciPost Physics 2 (2017), Art. 016 / arXiv:1611.02269', '[SINNGEMAESSER BELEG - NICHT WORTWOERTLICH] Verlinde formuliert in einem theoretischen Forschungsartikel einen Ansatz, der Raumzeit und Gravitation aus quanteninformationellen Verschränkungsstrukturen hervorgehen lässt; die These ist modellabhängig und Gegenstand wissenschaftlicher Prüfung.\n[DIREKT_GEPRUEFT] \"spacetime and gravity emerge together from the entanglement structure of an underlying microscopic theory\"', 'Eine einzelne theoretische Position darf nicht zu physikalischem Fachkonsens verallgemeinert werden. Originalmanuskript und Einzelaussagen müssen eigenstaendig geprüft werden.', 'Originaltext/Zitatstatus: DIREKT_GEPRUEFT\nFundort: Abstract, SciPost Physics 2 (2017), Art. 016 / arXiv:1611.02269\nRecherche-URL: https://arxiv.org/abs/1611.02269\nKeine implizite Freigabe der Seitenzitate oder des FRZK.', 'draft', NULL),
(3, 3, 'DEEP RESEARCH 2026-10-17 | Quelle [3]: Von Foersters Werk versammelt kybernetische Beiträge über Beobachtung, erkenntnistheoretische Selbstbezüglichkeit und selbstorganisierende Systeme.', 'Fachlicher Kontext für Kapitel 1. Quellenbeleg ist von eigener FRZK-Behauptung zu trennen.', 'Zitierte Quelle [3] / Kapitel 1; Open Library, Katalogeintrag für die Ausgabe 1981, Seitenangabe offen', '[SINNGEMAESSER BELEG - NICHT WORTWOERTLICH] Von Foersters Werk versammelt kybernetische Beiträge über Beobachtung, erkenntnistheoretische Selbstbezüglichkeit und selbstorganisierende Systeme.', 'Nur Werkzuordnung und Themenkatalog geprüft; kein wörtliches Buchzitat und keine Belegseite verifiziert. Originalmanuskript und Einzelaussagen müssen eigenstaendig geprüft werden.', 'Originaltext/Zitatstatus: NUR_INDIREKT\nFundort: Open Library, Katalogeintrag für die Ausgabe 1981, Seitenangabe offen\nRecherche-URL: https://openlibrary.org/books/OL13550910M/Observing_systems\nKeine implizite Freigabe der Seitenzitate oder des FRZK.', 'draft', NULL),
(4, 4, 'DEEP RESEARCH 2026-10-17 | Quelle [4]: Maturana und Varela behandeln lebende Systeme, Autopoiesis, strukturelle Kopplung und die biologischen Grundlagen des Erkennens. Dies deckt nicht automatisch von Foersters Beobachtung zweiter Ordnung ab.', 'Fachlicher Kontext für Kapitel 1. Quellenbeleg ist von eigener FRZK-Behauptung zu trennen.', 'Zitierte Quelle [4] / Kapitel 1; Google Books, Inhaltsverzeichnis der Ausgabe 1987: The Organization of Living Things ab S. 33', '[SINNGEMAESSER BELEG - NICHT WORTWOERTLICH] Maturana und Varela behandeln lebende Systeme, Autopoiesis, strukturelle Kopplung und die biologischen Grundlagen des Erkennens. Dies deckt nicht automatisch von Foersters Beobachtung zweiter Ordnung ab.', 'Autopoiesis in Biologie nicht ohne Argument auf mathematische oder didaktische FRZK-Operatoren übertragbar. Originalmanuskript und Einzelaussagen müssen eigenstaendig geprüft werden.', 'Originaltext/Zitatstatus: NUR_INDIREKT\nFundort: Google Books, Inhaltsverzeichnis der Ausgabe 1987: The Organization of Living Things ab S. 33\nRecherche-URL: https://books.google.com/books/about/The_Tree_of_Knowledge.html?id=8anuAAAAMAAJ\nKeine implizite Freigabe der Seitenzitate oder des FRZK.', 'draft', NULL),
(5, 5, 'DEEP RESEARCH 2026-10-17 | Quelle [5]: Reinmann beschreibt Design-Based Research als iterative und kontextsensitive Verbindung von Gestaltung, Forschung, Reflexion und Verbesserung der Bildungspraxis.', 'Fachlicher Kontext für Kapitel 1. Quellenbeleg ist von eigener FRZK-Behauptung zu trennen.', 'Zitierte Quelle [5] / Kapitel 1; Reinmann (2005), Unterrichtswissenschaft 33(1), S. 62, Abschnitt Forschungsstrategisches und -methodisches Vorgehen', '[SINNGEMAESSER BELEG - NICHT WORTWOERTLICH] Reinmann beschreibt Design-Based Research als iterative und kontextsensitive Verbindung von Gestaltung, Forschung, Reflexion und Verbesserung der Bildungspraxis.\n[DIREKT_GEPRUEFT] \"Entwicklung und Forschung finden in kontinuierlichen Zyklen von Gestaltung, Durchführung, Analyse und Re-Design statt\"', 'Stützt iterative Designforschung, beweist aber nicht allgemein emergente Raumzeitstrukturen von Lernprozessen. Originalmanuskript und Einzelaussagen müssen eigenstaendig geprüft werden.', 'Originaltext/Zitatstatus: DIREKT_GEPRUEFT\nFundort: Reinmann (2005), Unterrichtswissenschaft 33(1), S. 62, Abschnitt Forschungsstrategisches und -methodisches Vorgehen\nRecherche-URL: https://www.pedocs.de/volltexte/2013/5787/pdf/UntWiss_2005_1_Reinmann_Innovation_ohne_Forschung.pdf\nKeine implizite Freigabe der Seitenzitate oder des FRZK.', 'draft', NULL),
(6, 6, 'DEEP RESEARCH 2026-10-17 | Quelle [6]: Arnolds LENA-Modell empfiehlt, Lernprozesse anzuregen, zu arrangieren, zu begleiten und reflexiv zu gestalten; zentral sind Lernendenorientierung und Selbsttätigkeit.', 'Fachlicher Kontext für Kapitel 1. Quellenbeleg ist von eigener FRZK-Behauptung zu trennen.', 'Zitierte Quelle [6] / Kapitel 1; Carl-Auer-Verlag, offizieller Buchbeschreibungstext zur 2012 erschienenen Erstauflage', '[SINNGEMAESSER BELEG - NICHT WORTWOERTLICH] Arnolds LENA-Modell empfiehlt, Lernprozesse anzuregen, zu arrangieren, zu begleiten und reflexiv zu gestalten; zentral sind Lernendenorientierung und Selbsttätigkeit.', 'Verlagsbeschreibung ist kein nachgewiesenes wörtliches Zitat des Buchautors; keine Seitenangabe geprüft. Originalmanuskript und Einzelaussagen müssen eigenstaendig geprüft werden.', 'Originaltext/Zitatstatus: NUR_INDIREKT\nFundort: Carl-Auer-Verlag, offizieller Buchbeschreibungstext zur 2012 erschienenen Erstauflage\nRecherche-URL: https://www.carl-auer.de/wie-man-lehrt-ohne-zu-belehren\nKeine implizite Freigabe der Seitenzitate oder des FRZK.', 'draft', NULL),
(7, 7, 'DEEP RESEARCH 2026-10-17 | Quelle [7]: Rovelli diskutiert, dass bestimmte verbreitete Vorstellungen einer einheitlichen und universellen Zeit auf fundamentaler Ebene nicht direkt gelten. Dies belegt keine FRZK-Initialisierung aus der leeren Menge.', 'Fachlicher Kontext für Kapitel 1. Quellenbeleg ist von eigener FRZK-Behauptung zu trennen.', 'Zitierte Quelle [7] / Kapitel 1; Penguin Random House, Buchbeschreibung 2018; Physics Today, Autoreninterview (andere Quelle)', '[SINNGEMAESSER BELEG - NICHT WORTWOERTLICH] Rovelli diskutiert, dass bestimmte verbreitete Vorstellungen einer einheitlichen und universellen Zeit auf fundamentaler Ebene nicht direkt gelten. Dies belegt keine FRZK-Initialisierung aus der leeren Menge.', 'Buchseite S. 36 ff. nicht anhand Originalausgabe geprüft; kein direkter Schluss auf Emergenz geometrischer Achsen. Originalmanuskript und Einzelaussagen müssen eigenstaendig geprüft werden.', 'Originaltext/Zitatstatus: NUR_INDIREKT\nFundort: Penguin Random House, Buchbeschreibung 2018; Physics Today, Autoreninterview (andere Quelle)\nRecherche-URL: https://www.penguinrandomhouse.com/books/551483/the-order-of-time-by-carlo-rovelli/9780735216129\nKeine implizite Freigabe der Seitenzitate oder des FRZK.', 'draft', NULL),
(8, 8, 'DEEP RESEARCH 2026-10-17 | Quelle [8]: Luhmann entwickelt eine Theorie sozialer Systeme mit Selbstreferenz, System/Umwelt-Unterscheidung, Sinn und autopoietischer Reproduktion; Anwendbarkeit auf Beobachtungsprozesse ist zu erläutern.', 'Fachlicher Kontext für Kapitel 1. Quellenbeleg ist von eigener FRZK-Behauptung zu trennen.', 'Zitierte Quelle [8] / Kapitel 1; Suhrkamp-Ausgabe 1984; Google Books Inhaltsverzeichnis: Paradigmawechsel S.15 und System und Funktion S.30', '[SINNGEMAESSER BELEG - NICHT WORTWOERTLICH] Luhmann entwickelt eine Theorie sozialer Systeme mit Selbstreferenz, System/Umwelt-Unterscheidung, Sinn und autopoietischer Reproduktion; Anwendbarkeit auf Beobachtungsprozesse ist zu erläutern.', 'Eine Seitenangabe S. 46 ff. ist nicht textgenau gegen die Erstausgabe verifiziert. Originalmanuskript und Einzelaussagen müssen eigenstaendig geprüft werden.', 'Originaltext/Zitatstatus: NUR_INDIREKT\nFundort: Suhrkamp-Ausgabe 1984; Google Books Inhaltsverzeichnis: Paradigmawechsel S.15 und System und Funktion S.30\nRecherche-URL: https://books.google.com/books/about/Soziale_Systeme.html?id=13cSAQAAMAAJ\nKeine implizite Freigabe der Seitenzitate oder des FRZK.', 'draft', NULL),
(9, 9, 'DEEP RESEARCH 2026-10-17 | Quelle [9]: Bruner betont die Bedeutung grundlegender Fachstrukturen und eines spiralförmig vertieften Curriculums: intuitive Grundideen werden später stärker formalisiert.', 'Fachlicher Kontext für Kapitel 1.1.2. Quellenbeleg ist von eigener FRZK-Behauptung zu trennen.', 'Zitierte Quelle [9] / Kapitel 1.1.2; Harvard University Press 1960; Inhaltsverzeichnis: The Importance of Structure S.17', '[SINNGEMAESSER BELEG - NICHT WORTWOERTLICH] Bruner betont die Bedeutung grundlegender Fachstrukturen und eines spiralförmig vertieften Curriculums: intuitive Grundideen werden später stärker formalisiert.', 'Reduzierung des Verständnisses ausschließlich auf bereits vorhandene Bezugssysteme wäre zu streng; Seiten 17-20 nicht vollständig eingesehen. Originalmanuskript und Einzelaussagen müssen eigenstaendig geprüft werden.', 'Originaltext/Zitatstatus: NUR_INDIREKT\nFundort: Harvard University Press 1960; Inhaltsverzeichnis: The Importance of Structure S.17\nRecherche-URL: https://books.google.com/books/about/The_Process_of_Education.html?id=M5VqAAAAMAAJ\nKeine implizite Freigabe der Seitenzitate oder des FRZK.', 'draft', NULL),
(10, 10, 'DEEP RESEARCH 2026-10-17 | Quelle [10]: Ausubel begründet bedeutungsvolles Lernen über den Anschluss neuer Inhalte an relevante vorhandene kognitive Begriffe und Wissensstrukturen.', 'Fachlicher Kontext für Kapitel 1.1.2. Quellenbeleg ist von eigener FRZK-Behauptung zu trennen.', 'Zitierte Quelle [10] / Kapitel 1.1.2; Online-Textkopie, Abschnitt Cognitive Structure Variables; Ausgabe 1963, Seitenverifizierung offen', '[SINNGEMAESSER BELEG - NICHT WORTWOERTLICH] Ausubel begründet bedeutungsvolles Lernen über den Anschluss neuer Inhalte an relevante vorhandene kognitive Begriffe und Wissensstrukturen.\n[TRANSKRIPT_UNBESTAETIGT] \"Potentially meaningful material is always learned in relation to an existing background of relevant concepts\"', 'Formulierung in nichtautorisierter Dritttranskription gefunden; bis zum Editionsabgleich nicht als gesichertes Direktzitat freigeben. Originalmanuskript und Einzelaussagen müssen eigenstaendig geprüft werden.', 'Originaltext/Zitatstatus: TRANSKRIPT_UNBESTAETIGT\nFundort: Online-Textkopie, Abschnitt Cognitive Structure Variables; Ausgabe 1963, Seitenverifizierung offen\nRecherche-URL: https://www.scribd.com/document/899638684/Ausubel-D-1963-the-Psychology-of-Meaningful-Verbal-Learning\nKeine implizite Freigabe der Seitenzitate oder des FRZK.', 'draft', NULL),
(11, 11, 'DEEP RESEARCH 2026-10-17 | Quelle [11]: Sfard fasst mathematisches Denken als kommunikativen, teilweise rekursiv selbstbezüglichen Diskurs auf. Dies begründet die Analyse von Verständigungs- und Deutungsprozessen.', 'Fachlicher Kontext für Kapitel 1. Quellenbeleg ist von eigener FRZK-Behauptung zu trennen.', 'Zitierte Quelle [11] / Kapitel 1; Cambridge University Press, Originaltext-Auszug, Kap. 4 Thinking in Language (S. 94-124; konkrete Satzseite offen)', '[SINNGEMAESSER BELEG - NICHT WORTWOERTLICH] Sfard fasst mathematisches Denken als kommunikativen, teilweise rekursiv selbstbezüglichen Diskurs auf. Dies begründet die Analyse von Verständigungs- und Deutungsprozessen.\n[DIREKT_GEPRUEFT] \"all forms of communication need to be considered, not just verbal\"', 'Keine empirische Prüfung der Wirksamkeit des FRZK, und im DOCX genannte S.33-55 für dieses Zitat nicht nachgewiesen. Originalmanuskript und Einzelaussagen müssen eigenstaendig geprüft werden.', 'Originaltext/Zitatstatus: DIREKT_GEPRUEFT\nFundort: Cambridge University Press, Originaltext-Auszug, Kap. 4 Thinking in Language (S. 94-124; konkrete Satzseite offen)\nRecherche-URL: https://www.cambridge.org/core/books/abs/thinking-as-communicating/thinking-in-language/C059574BA642D25B860F23A2B144FCDC\nKeine implizite Freigabe der Seitenzitate oder des FRZK.', 'draft', NULL),
(12, 12, 'DEEP RESEARCH 2026-10-17 | Quelle [12]: Hatties Metasynthese thematisiert Einflüsse auf schulische Leistungen, insbesondere Feedback, Lehrhandeln und Beziehungen. Die Evidenz ist auf konkrete Faktoren und Kontexte zu begrenzen.', 'Fachlicher Kontext für Kapitel 1.3. Quellenbeleg ist von eigener FRZK-Behauptung zu trennen.', 'Zitierte Quelle [12] / Kapitel 1.3; Routledge, Originalverlagsbeschreibung, Visible Learning (2009)', '[SINNGEMAESSER BELEG - NICHT WORTWOERTLICH] Hatties Metasynthese thematisiert Einflüsse auf schulische Leistungen, insbesondere Feedback, Lehrhandeln und Beziehungen. Die Evidenz ist auf konkrete Faktoren und Kontexte zu begrenzen.', 'Die Stelle S.118-122 wurde nicht gegen die Buchausgabe geprüft; Stärke und Ursache der Lernatmosphäre sind nicht durch pauschale Formulierung abgedeckt. Originalmanuskript und Einzelaussagen müssen eigenstaendig geprüft werden.', 'Originaltext/Zitatstatus: NUR_INDIREKT\nFundort: Routledge, Originalverlagsbeschreibung, Visible Learning (2009)\nRecherche-URL: https://www.routledge.com/Visible-Learning-ASynthesis-of-Over-800-Meta-Analyses-Relating-toAchievement/Hattie/p/book/9780415476188\nKeine implizite Freigabe der Seitenzitate oder des FRZK.', 'draft', NULL),
(13, 13, 'DEEP RESEARCH 2026-10-17 | Quelle [13]: Carroll verbindet Naturwissenschaft und philosophischen Naturalismus und unterscheidet Erklärungsebenen, ohne damit die Emergenz eines konkreten didaktischen Lernmodells zu bestätigen.', 'Fachlicher Kontext für Kapitel 1.2. Quellenbeleg ist von eigener FRZK-Behauptung zu trennen.', 'Zitierte Quelle [13] / Kapitel 1.2; Penguin Random House, Buchbeschreibung / Buchdaten 2016; Seiten S.221-230 offen', '[SINNGEMAESSER BELEG - NICHT WORTWOERTLICH] Carroll verbindet Naturwissenschaft und philosophischen Naturalismus und unterscheidet Erklärungsebenen, ohne damit die Emergenz eines konkreten didaktischen Lernmodells zu bestätigen.', 'Nicht als direkte Stütze für die Behauptung eines fortlaufenden selbstorganisierten Wissensprozesses belegt. Originalmanuskript und Einzelaussagen müssen eigenstaendig geprüft werden.', 'Originaltext/Zitatstatus: NUR_INDIREKT\nFundort: Penguin Random House, Buchbeschreibung / Buchdaten 2016; Seiten S.221-230 offen\nRecherche-URL: https://www.penguinrandomhouse.com/books/316646/the-big-picture-by-sean-carroll/9780698409767/\nKeine implizite Freigabe der Seitenzitate oder des FRZK.', 'draft', NULL),
(14, 14, 'DEEP RESEARCH 2026-10-17 | Quelle [14]: Taschners Vortrag erläutert an einem geometrischen Rätsel, dass die Interpretation einer mathematischen Frage von der jeweiligen Lesart und Aufgabenstellung abhängen kann.', 'Fachlicher Kontext für Kapitel 1.1.3. Quellenbeleg ist von eigener FRZK-Behauptung zu trennen.', 'Zitierte Quelle [14] / Kapitel 1.1.3; Aufzeichnung des Vortrags vom 25.09.2013, veröffentlicht 27.09.2013, math.space Wien', '[SINNGEMAESSER BELEG - NICHT WORTWOERTLICH] Taschners Vortrag erläutert an einem geometrischen Rätsel, dass die Interpretation einer mathematischen Frage von der jeweiligen Lesart und Aufgabenstellung abhängen kann.', 'Das im DOCX angeführte vermeintliche Wortzitat und das Bild sind nicht mit einem Video-Zeitstempel belegt; kein gesichertes Originalzitat. Originalmanuskript und Einzelaussagen müssen eigenstaendig geprüft werden.', 'Originaltext/Zitatstatus: NUR_INDIREKT\nFundort: Aufzeichnung des Vortrags vom 25.09.2013, veröffentlicht 27.09.2013, math.space Wien\nRecherche-URL: https://www.youtube.com/watch?v=Dt7Ihzyae6I\nKeine implizite Freigabe der Seitenzitate oder des FRZK.', 'draft', NULL);

