  `revision_id` bigint(20) UNSIGNED NOT NULL,
  `document_id` bigint(20) UNSIGNED NOT NULL,
  `file_sha256` char(64) NOT NULL,
  `text_sha256` char(64) NOT NULL,
  `full_text` longtext NOT NULL,
  `numbered_sections` int(10) UNSIGNED NOT NULL,
  `citations` int(10) UNSIGNED NOT NULL,
  `first_citations` int(10) UNSIGNED NOT NULL,
  `active_equations` int(10) UNSIGNED NOT NULL,
  `active_definitions` int(10) UNSIGNED NOT NULL,
  `status` varchar(32) NOT NULL DEFAULT 'review',
  `notes` text DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp()
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

