INSERT INTO `rkb1_lit_source_evidence` (`evidence_id`, `revision_id`, `source_id`, `citation_number`, `evidence_class`, `claim_fit`, `evidence_url`, `verified_scope`, `limitations`, `exact_page_verified`) VALUES
(1, 7, 1, 1, 'publisher_description', 'background_only', 'https://www.penguinrandomhouse.com/books/549244/reality-is-not-what-it-seems-by-carlo-rovelli-translated-by-simon-carnell-and-erica-segre/', 'Rovelli behandelt Grenzfragen zeitgenoessischer theoretischer Physik. Kein unmittelbarer didaktischer Beleg.', 'Ausgabe und Jahr 2016 in Literaturangabe gegen konkrete Printausgabe abgleichen. Keine exakte Textseite geprueft.', 0),
(2, 7, 2, 2, 'primary_article_abstract', 'thematic_fit', 'https://doi.org/10.21468/SciPostPhys.2.3.016', 'Verlinde entwickelt eine theoretische Hypothese zu emergenter Gravitation. Im Kapitel korrekt als umstrittener Modellansatz eingeordnet.', 'Fachartikel bibliographisch gesichert; kein experimenteller Nachweis fuer das FRZK.', 0),
(3, 7, 3, 3, 'bibliographic_context', 'limited_fit', 'https://openlibrary.org/search?q=Heinz+von+Foerster+Observing+Systems+1981', 'Beobachtung und Kybernetik als Hintergrund; konkrete Behauptungen ueber Beobachtung zweiter Ordnung erfordern Originaltext.', 'Buchseiten nicht eingesehen; keine quote-genaue Quelle.', 0),
(4, 7, 4, 4, 'bibliographic_context', 'limited_fit', 'https://openlibrary.org/search?q=Maturana+Varela+The+Tree+of+Knowledge+1987', 'Kognition und biologische Erkenntnistheorie als Hintergrund, nicht direkte FRZK-Validierung.', 'Autopoiesis und Beobachtung hier nur thematisch, Buchseiten nicht eingesehen.', 0),
(5, 7, 5, 5, 'peer_reviewed_article_metadata', 'thematic_fit', 'https://www.pedocs.de/frontdoor.php?source_opus=5787', 'Reinmann behandelt explizit die Rolle des Designs in gestaltungsorientierter Lehr-Lernforschung.', 'Jahrgang, Heft und Artikelumfang 52-69 gesichert; satzgenaue Seitenstelle noch nicht fuer alle Aussagen belegt.', 0),
(6, 7, 6, 6, 'publisher_description', 'thematic_fit', 'https://www.carl-auer.de/wie-man-lehrt-ohne-zu-belehren', 'Arnold behandelt Lernbegleitung, selbststaendiges Lernen und LENA als didaktisches Konzept.', 'Verlagsdarstellung sichert die thematische Einordnung; Textseiten der 2012-Ausgabe nicht eingesehen.', 0),
(7, 7, 7, 7, 'publisher_description', 'thematic_fit', 'https://www.penguinrandomhouse.com/books/551483/the-order-of-time-by-carlo-rovelli/', 'Rovelli diskutiert wissenschaftliche und philosophische Grundfragen der Zeit. Keine physikalische FRZK-Bestaetigung.', 'Originale Angabe S.36 ff. entfernt; Ausgabe und Seitenzahl waren nicht verifiziert.', 0),
(8, 7, 8, 8, 'publisher_description', 'thematic_fit', 'https://www.suhrkamp.de/buch/niklas-luhmann-soziale-systeme-t-9783518282663', 'Luhmanns Systemtheorie ist ein begrifflicher Hintergrund, kein allgemeiner Rekursionszwang im FRZK.', 'Originale Angabe S.46 ff. entfernt; genaue Seitenstelle nicht geprueft.', 0),
(9, 7, 9, 9, 'publisher_description', 'thematic_fit', 'https://www.harvard.com/book/9780674710016', 'Bruner diskutiert die Struktur und schrittweise Vertiefung von Lehrinhalten.', 'Vorliegende Verlags-/Buchhaendlerbeschreibung zur revidierten Ausgabe; 1960er Seiten 17-20 nicht editionsgenau verifiziert.', 0),
(10, 7, 10, 10, 'related_primary_article', 'limited_fit', 'https://doi.org/10.1177/002248716301400220', 'Ausubels nachgewiesener Fachartikel (1963) behandelt kognitive Struktur, waehrend die zitierte Monographie nicht seitenweise eingesehen wurde.', 'Verwandter Originalartikel ist nicht mit der im Literaturverzeichnis zitierten Monographie gleichzusetzen.', 0),
(11, 7, 11, 11, 'publisher_chapter_description', 'thematic_fit', 'https://www.cambridge.org/core/books/thinking-as-communicating/4AD97425F28C43AC894B4658CDA6DB24', 'Sfard erlaeutert mathematisches Denken als Kommunikation und analysiert mathematische Diskurse.', 'Seiten 33-55 wurden entfernt; konkrete Argumentation in der Leseprobe nicht auf diesen Umfang verifiziert.', 0),
(12, 7, 12, 12, 'publisher_description', 'thematic_fit', 'https://www.routledge.com/Visible-Learning-for-Teachers-Maximize-Learning-Impact/John-Hattie/p/book/9780415476188', 'Hattie behandelt auf Basis vieler Metaanalysen u. a. Feedback und unterrichtliche Faktoren; keine FRZK-Effektstaerke.', 'Die pauschale Aussage ueber Lernatmosphaere sowie S.118-122 wurden eingeschraenkt/entfernt.', 0),
(13, 7, 13, 13, 'publisher_description', 'background_only', 'https://www.penguinrandomhouse.com/books/316646/the-big-picture-by-sean-carroll/', 'Carroll als Hintergrund fuer naturwissenschaftliche und philosophische Erklaerungsebenen.', 'Kein fachlicher Beleg fuer didaktischen Nutzen; S.221-230 entfernt.', 0),
(14, 7, 14, 14, 'archival_video_metadata', 'thematic_fit', 'https://av.tib.eu/media/15789', 'Vortrag mit Autor, Datum, DOI und CC BY-NC 3.0 DE im TIB AV-Portal identifizierbar.', 'Genaue Abbildung, Sequenz/Timecode und spezifische Nutzung/Rechte noch gesondert pruefen.', 0);

